* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
    min-height: 100vh;
    overflow: hidden;
    color: #fff;
}

#app {
    position: relative;
    width: 100vw;
    height: 100vh;
}

#avatar-container {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 300px;
    height: 300px;
    cursor: pointer;
}

#avatar-canvas {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    box-shadow: 0 0 40px rgba(100, 200, 255, 0.3);
    transition: box-shadow 0.3s ease;
}

#avatar-container.speaking #avatar-canvas {
    box-shadow: 0 0 60px rgba(100, 200, 255, 0.6);
    animation: pulse-glow 1s ease-in-out infinite;
}

#avatar-container.listening #avatar-canvas {
    box-shadow: 0 0 60px rgba(255, 200, 100, 0.6);
    animation: pulse-glow 0.5s ease-in-out infinite;
}

#avatar-container.private-mode #avatar-canvas {
    box-shadow: 0 0 20px rgba(100, 100, 100, 0.3);
    filter: grayscale(0.8) brightness(0.6);
}

@keyframes pulse-glow {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.05); }
}

#emotion-indicator {
    position: absolute;
    bottom: -30px;
    left: 50%;
    transform: translateX(-50%);
    font-size: 24px;
    opacity: 0;
    transition: opacity 0.3s ease;
}

#emotion-indicator.visible {
    opacity: 1;
}

#controls {
    position: fixed;
    bottom: 30px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    gap: 20px;
    z-index: 100;
}

.control-btn {
    width: 70px;
    height: 70px;
    border-radius: 50%;
    border: none;
    background: linear-gradient(145deg, #2a2a4a, #1a1a3a);
    color: #fff;
    cursor: pointer;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 4px;
    transition: all 0.3s ease;
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.3);
}

.control-btn:hover {
    transform: translateY(-3px);
    box-shadow: 0 6px 20px rgba(100, 200, 255, 0.4);
}

.control-btn:active {
    transform: translateY(0);
}

.control-btn.active {
    background: linear-gradient(145deg, #4a4a8a, #3a3a7a);
    box-shadow: 0 0 25px rgba(100, 200, 255, 0.5);
}

.control-btn .icon {
    font-size: 20px;
}

.control-btn .label {
    font-size: 9px;
    opacity: 0.8;
}

.control-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

#thinking-panel, #chat-panel, #settings-panel {
    position: fixed;
    right: 20px;
    top: 20px;
    width: 380px;
    max-height: 80vh;
    background: rgba(30, 30, 60, 0.95);
    border-radius: 16px;
    backdrop-filter: blur(10px);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.5);
    z-index: 200;
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

#thinking-panel.hidden, #chat-panel.hidden, #settings-panel.hidden {
    display: none;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 20px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}

.panel-header h3 {
    font-size: 16px;
    font-weight: 500;
}

.panel-header button {
    background: none;
    border: none;
    color: #fff;
    font-size: 20px;
    cursor: pointer;
    opacity: 0.7;
    transition: opacity 0.2s;
}

.panel-header button:hover {
    opacity: 1;
}

#thinking-content, #chat-messages {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
}

.thinking-entry {
    margin-bottom: 12px;
    padding: 12px;
    background: rgba(255, 255, 255, 0.05);
    border-radius: 8px;
    font-size: 13px;
    line-height: 1.5;
}

.thinking-entry .timestamp {
    font-size: 11px;
    opacity: 0.5;
    margin-bottom: 4px;
}

.thinking-entry .type {
    font-weight: 600;
    margin-bottom: 4px;
    color: #64c8ff;
}

.chat-message {
    margin-bottom: 12px;
    padding: 12px;
    border-radius: 12px;
    max-width: 85%;
    font-size: 14px;
    line-height: 1.4;
}

.chat-message.user {
    background: rgba(100, 150, 255, 0.3);
    margin-left: auto;
    border-bottom-right-radius: 4px;
}

.chat-message.assistant {
    background: rgba(255, 255, 255, 0.1);
    margin-right: auto;
    border-bottom-left-radius: 4px;
}

#chat-status {
    padding: 12px 16px;
    font-size: 12px;
    opacity: 0.6;
    text-align: center;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
}

.settings-content {
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.settings-content label {
    display: flex;
    flex-direction: column;
    gap: 6px;
    font-size: 14px;
}

.settings-content input,
.settings-content select,
.settings-content textarea {
    padding: 10px 12px;
    border-radius: 8px;
    border: 1px solid rgba(255, 255, 255, 0.2);
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
    font-size: 14px;
}

.settings-content textarea {
    min-height: 80px;
    resize: vertical;
}

.settings-content button {
    padding: 12px;
    border-radius: 8px;
    border: none;
    background: linear-gradient(145deg, #4a6fa5, #3a5a8a);
    color: #fff;
    font-size: 14px;
    cursor: pointer;
    transition: all 0.3s;
}

.settings-content button:hover {
    transform: translateY(-2px);
    box-shadow: 0 4px 15px rgba(100, 150, 255, 0.4);
}

::-webkit-scrollbar {
    width: 6px;
}

::-webkit-scrollbar-track {
    background: transparent;
}

::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.2);
    border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.3);
}

class VtuberAI {
    constructor() {
        this.canvas = document.getElementById('avatar-canvas');
        this.ctx = this.canvas.getContext('2d');
        this.avatarContainer = document.getElementById('avatar-container');
        this.emotionIndicator = document.getElementById('emotion-indicator');

        this.isListening = false;
        this.isSpeaking = false;
        this.isPrivateMode = false;
        this.currentEmotion = 'neutral';

        this.settings = {
            apiKey: '',
            apiUrl: 'https://api.mimo.ai/v1',
            tts: 'edge',
            characterRole: 'Ты дружелюбный AI-компаньон с мягким характером. Ты помогаешь и поддерживаешь.'
        };

        this.conversationHistory = [];
        this.thinkingLog = [];

        this.recognition = null;
        this.synthesis = window.speechSynthesis;

        this.init();
    }

    init() {
        this.setupCanvas();
        this.setupEventListeners();
        this.setupSpeechRecognition();
        this.loadSettings();
        this.startAnimationLoop();
        this.drawAvatar();
    }

    setupCanvas() {
        this.canvas.width = 300;
        this.canvas.height = 300;
    }

    setupEventListeners() {
        document.getElementById('btn-talk').addEventListener('click', () => this.toggleListening());
        document.getElementById('btn-vision').addEventListener('click', () => this.togglePrivateMode());
        document.getElementById('btn-thinking').addEventListener('click', () => this.togglePanel('thinking-panel'));
        document.getElementById('btn-close-thinking').addEventListener('click', () => this.hidePanel('thinking-panel'));
        document.getElementById('btn-close-chat').addEventListener('click', () => this.hidePanel('chat-panel'));
        document.getElementById('btn-close-settings').addEventListener('click', () => this.hidePanel('settings-panel'));
        document.getElementById('btn-save-settings').addEventListener('click', () => this.saveSettings());

        this.avatarContainer.addEventListener('dblclick', () => this.togglePanel('settings-panel'));
    }

    setupSpeechRecognition() {
        if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
            const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
            this.recognition = new SpeechRecognition();
            this.recognition.continuous = false;
            this.recognition.interimResults = true;
            this.recognition.lang = 'ru-RU';

            this.recognition.onresult = (event) => {
                const transcript = Array.from(event.results)
                    .map(result => result[0].transcript)
                    .join('');

                if (event.results[event.results.length - 1].isFinal) {
                    this.handleUserInput(transcript);
                }
            };

            this.recognition.onend = () => {
                this.isListening = false;
                this.avatarContainer.classList.remove('listening');
                document.getElementById('btn-talk').classList.remove('active');
            };

            this.recognition.onerror = (event) => {
                console.error('Speech recognition error:', event.error);
                this.isListening = false;
                this.avatarContainer.classList.remove('listening');
                document.getElementById('btn-talk').classList.remove('active');
            };
        }
    }

    toggleListening() {
        if (this.isListening) {
            this.recognition.stop();
        } else {
            this.isListening = true;
            this.avatarContainer.classList.add('listening');
            document.getElementById('btn-talk').classList.add('active');
            this.setEmotion('listening');
            this.recognition.start();
        }
    }

    togglePrivateMode() {
        this.isPrivateMode = !this.isPrivateMode;
        const btn = document.getElementById('btn-vision');

        if (this.isPrivateMode) {
            this.avatarContainer.classList.add('private-mode');
            btn.classList.add('active');
            this.setEmotion('privacy');
            this.logThinking('Система', 'Приватный режим активирован. Зрение отключено.');
        } else {
            this.avatarContainer.classList.remove('private-mode');
            btn.classList.remove('active');
            this.setEmotion('neutral');
            this.logThinking('Система', 'Приватный режим деактивирован. Зрение восстановлено.');
        }
    }

    togglePanel(panelId) {
        const panel = document.getElementById(panelId);
        panel.classList.toggle('hidden');
    }

    hidePanel(panelId) {
        document.getElementById(panelId).classList.add('hidden');
    }

    setEmotion(emotion) {
        this.currentEmotion = emotion;
        const emotions = {
            neutral: '😊',
            listening: '👂',
            speaking: '💬',
            thinking: '🤔',
            privacy: '😴',
            happy: '😊',
            surprised: '😮',
            concerned: '😟'
        };

        this.emotionIndicator.textContent = emotions[emotion] || '😊';
        this.emotionIndicator.classList.add('visible');
    }

    drawAvatar() {
        const ctx = this.ctx;
        const w = this.canvas.width;
        const h = this.canvas.height;
        const centerX = w / 2;
        const centerY = h / 2;

        ctx.clearRect(0, 0, w, h);

        const gradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, 150);
        gradient.addColorStop(0, '#4a90d9');
        gradient.addColorStop(0.7, '#357abd');
        gradient.addColorStop(1, '#2a5a8a');

        ctx.beginPath();
        ctx.arc(centerX, centerY, 140, 0, Math.PI * 2);
        ctx.fillStyle = gradient;
        ctx.fill();

        ctx.beginPath();
        ctx.arc(centerX, centerY, 140, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.lineWidth = 3;
        ctx.stroke();

        this.drawFace(ctx, centerX, centerY);
    }

    drawFace(ctx, cx, cy) {
        const eyeY = cy - 20;
        const eyeSpacing = 40;

        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.ellipse(cx - eyeSpacing, eyeY, 18, 22, 0, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.ellipse(cx + eyeSpacing, eyeY, 18, 22, 0, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = '#1a1a2e';
        let pupilOffsetX = 0;
        let pupilOffsetY = 0;

        if (this.isListening) {
            pupilOffsetY = 3;
        } else if (this.isSpeaking) {
            pupilOffsetX = Math.sin(Date.now() / 100) * 3;
        }

        ctx.beginPath();
        ctx.arc(cx - eyeSpacing + pupilOffsetX, eyeY + pupilOffsetY, 10, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(cx + eyeSpacing + pupilOffsetX, eyeY + pupilOffsetY, 10, 0, Math.PI * 2);
        ctx.fill();

        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
        ctx.beginPath();
        ctx.arc(cx - eyeSpacing + 4, eyeY - 4, 4, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.arc(cx + eyeSpacing + 4, eyeY - 4, 4, 0, Math.PI * 2);
        ctx.fill();

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 3;
        ctx.lineCap = 'round';

        ctx.beginPath();
        if (this.isSpeaking) {
            const mouthOpen = Math.abs(Math.sin(Date.now() / 150)) * 15 + 5;
            ctx.ellipse(cx, cy + 40, 20, mouthOpen, 0, 0, Math.PI * 2);
            ctx.fillStyle = 'rgba(255, 100, 100, 0.6)';
            ctx.fill();
        } else if (this.currentEmotion === 'happy') {
            ctx.arc(cx, cy + 30, 25, 0.1 * Math.PI, 0.9 * Math.PI);
            ctx.stroke();
        } else {
            ctx.arc(cx, cy + 35, 15, 0.2 * Math.PI, 0.8 * Math.PI);
            ctx.stroke();
        }

        ctx.fillStyle = 'rgba(255, 150, 150, 0.3)';
        ctx.beginPath();
        ctx.ellipse(cx - 60, cy + 10, 15, 10, -0.3, 0, Math.PI * 2);
        ctx.fill();
        ctx.beginPath();
        ctx.ellipse(cx + 60, cy + 10, 15, 10, 0.3, 0, Math.PI * 2);
        ctx.fill();
    }

    startAnimationLoop() {
        const animate = () => {
            this.drawAvatar();
            requestAnimationFrame(animate);
        };
        animate();
    }

    async handleUserInput(text) {
        if (!text.trim()) return;

        this.addChatMessage('user', text);
        this.setEmotion('thinking');
        this.logThinking('Пользователь', text);

        try {
            const response = await this.getAIResponse(text);
            this.addChatMessage('assistant', response);
            this.logThinking('AI Ответ', response);
            this.speak(response);
        } catch (error) {
            console.error('Error getting AI response:', error);
            this.logThinking('Ошибка', error.message);
            this.setEmotion('concerned');
        }
    }

    async getAIResponse(userMessage) {
        this.logThinking('Запрос к API', `Отправка сообщения: ${userMessage}`);

        const messages = [
            { role: 'system', content: this.settings.characterRole },
            ...this.conversationHistory.slice(-10),
            { role: 'user', content: userMessage }
        ];

        const response = await fetch(`${this.settings.apiUrl}/chat/completions`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${this.settings.apiKey}`
            },
            body: JSON.stringify({
                model: 'mimo-free',
                messages: messages,
                temperature: 0.7,
                max_tokens: 500
            })
        });

        if (!response.ok) {
            throw new Error(`API error: ${response.status}`);
        }

        const data = await response.json();
        const aiResponse = data.choices[0].message.content;

        this.conversationHistory.push({ role: 'user', content: userMessage });
        this.conversationHistory.push({ role: 'assistant', content: aiResponse });

        return aiResponse;
    }

    speak(text) {
        if (this.settings.tts === 'local') {
            this.speakLocal(text);
        } else {
            this.speakEdge(text);
        }
    }

    speakLocal(text) {
        this.synthesis.cancel();

        const utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = 'ru-RU';
        utterance.rate = 1.0;
        utterance.pitch = 1.1;

        const voices = this.synthesis.getVoices();
        const russianVoice = voices.find(v => v.lang.startsWith('ru'));
        if (russianVoice) {
            utterance.voice = russianVoice;
        }

        utterance.onstart = () => {
            this.isSpeaking = true;
            this.avatarContainer.classList.add('speaking');
            this.setEmotion('speaking');
        };

        utterance.onend = () => {
            this.isSpeaking = false;
            this.avatarContainer.classList.remove('speaking');
            this.setEmotion('neutral');
        };

        this.synthesis.speak(utterance);
    }

    async speakEdge(text) {
        this.isSpeaking = true;
        this.avatarContainer.classList.add('speaking');
        this.setEmotion('speaking');

        try {
            const response = await fetch('https://speech.platform.bing.com/consumer/speech/synthesize/ogg/v1', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/ssml+xml',
                    'X-OutputFormat': 'audio-24khz-48kbitrate-mono-mp3'
                },
                body: `<speak version='1.0' xml:lang='ru-RU'><voice xml:lang='ru-RU' xml:gender='Female' name='ru-RU-SvetlanaNeural'>${text}</voice></speak>`
            });

            if (response.ok) {
                const audioBlob = await response.blob();
                const audioUrl = URL.createObjectURL(audioBlob);
                const audio = new Audio(audioUrl);

                audio.onended = () => {
                    this.isSpeaking = false;
                    this.avatarContainer.classList.remove('speaking');
                    this.setEmotion('neutral');
                    URL.revokeObjectURL(audioUrl);
                };

                await audio.play();
            } else {
                this.speakLocal(text);
            }
        } catch (error) {
            console.error('Edge TTS error:', error);
            this.speakLocal(text);
        }
    }

    addChatMessage(role, text) {
        const container = document.getElementById('chat-messages');
        const messageDiv = document.createElement('div');
        messageDiv.className = `chat-message ${role}`;
        messageDiv.textContent = text;
        container.appendChild(messageDiv);
        container.scrollTop = container.scrollHeight;
    }

    logThinking(type, content) {
        const timestamp = new Date().toLocaleTimeString();
        this.thinkingLog.push({ timestamp, type, content });

        const container = document.getElementById('thinking-content');
        const entryDiv = document.createElement('div');
        entryDiv.className = 'thinking-entry';
        entryDiv.innerHTML = `
            <div class="timestamp">${timestamp}</div>
            <div class="type">${type}</div>
            <div class="content">${content}</div>
        `;
        container.appendChild(entryDiv);
        container.scrollTop = container.scrollHeight;
    }

    loadSettings() {
        const saved = localStorage.getItem('vtuber-settings');
        if (saved) {
            this.settings = { ...this.settings, ...JSON.parse(saved) };
        }

        document.getElementById('api-key').value = this.settings.apiKey;
        document.getElementById('api-url').value = this.settings.apiUrl;
        document.getElementById('tts-select').value = this.settings.tts;
        document.getElementById('character-role').value = this.settings.characterRole;
    }

    saveSettings() {
        this.settings.apiKey = document.getElementById('api-key').value;
        this.settings.apiUrl = document.getElementById('api-url').value;
        this.settings.tts = document.getElementById('tts-select').value;
        this.settings.characterRole = document.getElementById('character-role').value;

        localStorage.setItem('vtuber-settings', JSON.stringify(this.settings));
        this.hidePanel('settings-panel');
        this.logThinking('Система', 'Настройки сохранены.');
    }
}

